import java.nio.file.*;import java.security.*;
class GenerateServiceKeys {public static void main(String[] a)throws Exception{Path p=Path.of(a[0]);Files.createDirectories(p);if(Files.exists(p.resolve("core-private.pk8")))throw new IllegalStateException("Do not replace existing keys");KeyPairGenerator g=KeyPairGenerator.getInstance("RSA");g.initialize(3072);KeyPair k=g.generateKeyPair();Files.write(p.resolve("core-private.pk8"),k.getPrivate().getEncoded(),StandardOpenOption.CREATE_NEW);Files.write(p.resolve("core-public.der"),k.getPublic().getEncoded(),StandardOpenOption.CREATE_NEW);}}
